// 1. Resolve contact source: check Upsert first (new contact path), then Fetch (existing contact path)
let leads = [];
try {
  leads = $('Upsert Contact in GHL').all();
} catch (e) {
  // upsert node was not executed in this run
}

if (!leads.length) {
  try {
    leads = $('Retrieve Contact from GHL').all();
  } catch (e) {
    // fallback to form trigger if GHL contacts were bypassed
    leads = $('When Form Submitted').all();
  }
}

const opportunityResults = $input.all();
const output = [];
const seenKeys = new Set();

// 2. Safely collect and deduplicate opportunities
const opportunitiesMap = new Map();

for (const item of opportunityResults) {
  const data = item.json || {};
  if (!data || Object.keys(data).length === 0) continue;

  const rawList = [];

  if (Array.isArray(data.opportunities)) {
    rawList.push(...data.opportunities);
  } else if (data.opportunity && typeof data.opportunity === 'object') {
    rawList.push(data.opportunity);
  } else if (data.id) {
    rawList.push(data);
  }

  for (const opp of rawList) {
    if (opp && opp.id && !opportunitiesMap.has(opp.id)) {
      opportunitiesMap.set(opp.id, opp);
    }
  }
}

const opportunities = Array.from(opportunitiesMap.values());

// Helper function to normalize phone numbers for comparison
const normalizePhone = (num) => {
  if (!num) return '';
  return String(num).replace(/\D/g, '').slice(-10);
};

// 3. Process incoming leads
for (const item of leads) {
  const data = item.json || {};
  const contact = (data.contact && typeof data.contact === 'object') ? data.contact : data;

  const contactId = contact.id || data.id || null;
  const rawPhone = contact.phone || data.phone || data['Phone number'] || null;
  const cleanPhone = normalizePhone(rawPhone);
  const email = (contact.email || data.email || '').toLowerCase().trim();

  // Deduplication key: prefer contactId, fallback to phone, then email
  const dedupKey = contactId || cleanPhone || email;
  if (!dedupKey || seenKeys.has(dedupKey)) {
    continue;
  }
  seenKeys.add(dedupKey);

  // 4. Match opportunities by contact ID, phone, or email
  const matchingOpportunity = opportunities.find((opp) => {
    const oppContactId = opp.contactId || opp.contact?.id || opp.contact_id;
    const oppPhone = normalizePhone(opp.contact?.phone || opp.phone);
    const oppEmail = (opp.contact?.email || opp.email || '').toLowerCase().trim();

    const matchesId = contactId && oppContactId && String(contactId) === String(oppContactId);
    const matchesPhone = cleanPhone && oppPhone && cleanPhone === oppPhone;
    const matchesEmail = email && oppEmail && email === oppEmail;

    return Boolean(matchesId || matchesPhone || matchesEmail);
  });

  const hasOpportunity = Boolean(matchingOpportunity);

  // Maintain id and names at top-level for Post Opportunity to CRM
  output.push({
    json: {
      ...contact,
      id: contactId,
      phone: rawPhone,
      email: email,
      lead_status: hasOpportunity ? 'old_opportunity' : 'new_opportunity',
      opportunity: matchingOpportunity || null
    }
  });
}

return output;

